const MAX_TRACKED_CLIENTS = 64;
const MAX_CHECKS_PER_CLIENT = 12;
const MAX_DIAGNOSTICS_PER_CLIENT = 4;
const MAX_TIMESTAMP_LENGTH = 32;
// Capping the number of clients is not enough on its own: one key just under the
